use std::env;
use std::fs;
use std::process;
use toml::Value;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 4 {
        eprintln!("Usage: cargo run --quiet -- <file.toml> <key.path>");
        process::exit(1);
    }

    let file_path = &args[1];
    let key_path = &args[2];

    match fs::read_to_string(file_path) {
        Ok(contents) => {
            match parse_toml(&contents, key_path) {
                Some(value) => println!("{}", value),
                None => {
                    eprintln!("Error: Key path '{}' not found in '{}'", key_path, file_path);
                    process::exit(1);
                }
            }
        }
        Err(_) => {
            eprintln!("Error: File '{}' not found", file_path);
            process::exit(1);
        }
    }
}

fn parse_toml(contents: &str, key_path: &str) -> Option<String> {
    let value = contents.parse::<Value>().ok()?;
    let keys: Vec<&str> = key_path.split('.').collect();
    let mut current_value = &value;

    for key in keys {
        current_value = match current_value {
            Value::Table(table) => table.get(key),
            _ => return None,
        };
    }

    current_value.as_str().map(|s| s.to_string())
}
```

