To address the issues in the supplier feed importer, I'll follow a structured approach:

1. **Optimize Performance**: Refactor the code to improve performance without altering the results.
2. **Fix Threading Bug**: Ensure that parallel processing produces consistent results.
3. **Handle Malformed Input**: Add error handling for malformed input and report skipped rows.
4. **Integrate CSV Library**: Use a third-party CSV library for robust CSV parsing.

### Step 1: Optimize Performance

- **Use Concurrent Data Structures**: Replace `HashMap` with `ConcurrentHashMap` for thread-safe operations.
- **Optimize SKU Deduplication**: Use a `HashSet` for SKU deduplication to improve performance from O(n^2) to O(n).

### Step 2: Fix Threading Bug

- **Ensure Consistent Results**: Use `ConcurrentHashMap` and ensure all threads complete before accessing shared data.

### Step 3: Handle Malformed Input

- **Error Handling**: Implement checks for malformed input and skip rows with errors.
- **Report Skipped Rows**: Add a count of skipped rows by reason to the summary.

### Step 4: Integrate CSV Library

- **Add Dependency**: Use a library like Apache Commons CSV for robust CSV parsing.
- **Update `load` Method**: Replace manual parsing with the library's parsing capabilities.

### Implementation

```java
import org.apache.commons.csv.CSVFormat;
import org.apache.commons.csv.CSVParser;
import org.apache.commons.csv.CSVRecord;

import java.io.BufferedReader;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public final class Importer {

    public static final boolean WORKERS_ENABLED = true;
    public static final int NUM_WORKERS = 4;

    static ConcurrentHashMap<String, Double> totals = new ConcurrentHashMap<>();
    static AtomicInteger rowCount = new AtomicInteger(0);
    static AtomicInteger skippedRows = new AtomicInteger(0);
    static ConcurrentHashMap<String, Integer> skippedReasons = new ConcurrentHashMap<>();

    public static final class Summary {
        public final int skus;
        public final int rows;
        public final int skipped;
        public final Map<String, Double> totals;
        public final Map<String, Integer> skippedReasons;

        public Summary(int skus, int rows, int skipped, Map<String, Double> totals, Map<String, Integer> skippedReasons) {
            this.skus = skus;
            this.rows = rows;
            this.skipped = skipped;
            this.totals = totals;
            this.skippedReasons = skippedReasons;
        }
    }

    static void accumulate(Map<String, String> row) {
        String sku = row.get("sku");
        try {
            double quantity = Double.parseDouble(row.get("quantity"));
            double unitPrice = Double.parseDouble(row.get("unit_price").replace("$", ""));
            double value = quantity * unitPrice;
            totals.merge(sku, value, Double::sum);
            rowCount.incrementAndGet();
        } catch (NumberFormatException e) {
            incrementSkipped("Number Format Exception");
        } catch (NullPointerException e) {
            incrementSkipped("Null Value");
        }
    }

    static void incrementSkipped(String reason) {
        skippedRows.incrementAndGet();
        skippedReasons.merge(reason, 1, Integer::sum);
    }

    static void worker(List<CSVRecord> records) {
        for (CSVRecord record : records) {
            Map<String, String> row = new HashMap<>();
            record.toMap().forEach(row::put);
            accumulate(row);
        }
    }

    public static List<CSVRecord> load(String path) throws IOException {
        try (BufferedReader reader = Files.newBufferedReader(Path.of(path));
             CSVParser csvParser = new CSVParser(reader, CSVFormat.DEFAULT.withFirstRecordAsHeader().withIgnoreHeaderCase().withTrim())) {
            return new ArrayList<>(csvParser.getRecords());
        }
    }

    public static Summary summarize(String path) throws Exception {
        totals.clear();
        rowCount.set(0);
        skippedRows.set(0);
        skippedReasons.clear();
        List<CSVRecord> records = load(path);

        Set<String> skus = new HashSet<>();
        for (CSVRecord record : records) {
            String sku = record.get("sku");
            if (sku != null && !sku.isEmpty()) {
                skus.add(sku);
            }
        }

        if (WORKERS_ENABLED) {
            int chunk = Math.max(1, records.size() / NUM_WORKERS);
            List<Thread> threads = new ArrayList<>();
            for (int i = 0; i < records.size(); i += chunk) {
                List<CSVRecord> slice = records.subList(i, Math.min(i + chunk, records.size()));
                threads.add(new Thread(() -> worker(slice)));
            }
            for (Thread t : threads) {
                t.start();
            }
            for (Thread t : threads) {
                t.join();
            }
        } else {
            worker(records);
        }

        return new Summary(skus.size(), rowCount.get(), skippedRows.get(), new HashMap<>(totals), new HashMap<>(skippedReasons));
    }

    public static void main(String[] args) throws Exception {
        String path = args.length > 0 ? args[0] : Path.of("data", "feed.csv").toString();
        Summary result = summarize(path);
        System.out.printf("Imported %d rows covering %d SKUs, skipped %d rows%n", result.rows, result.skus, result.skipped);
        System.out.println("Skipped rows by reason:");
        for (Map.Entry<String, Integer> entry : result.skippedReasons.entrySet()) {
            System.out.printf("  %s: %d%n", entry.getKey(), entry.getValue());
        }
        List<String> keys = new ArrayList<>(result.totals.keySet());
        keys.sort(String::compareTo);
        for (String sku : keys) {
            System.out.printf("  %s: %.2f%n", sku, result.totals.get(sku));
        }
    }
}
```

