import org.apache.commons.csv.CSVFormat;
import org.apache.commons.csv.CSVParser;
import org.apache.commons.csv.CSVRecord;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public final class Importer {

    public static final boolean WORKERS_ENABLED = true;
    public static final int NUM_WORKERS = 4;

    static ConcurrentHashMap<String, Double> totals = new ConcurrentHashMap<>();
    static AtomicInteger rowCount = new AtomicInteger(0);
    static AtomicInteger skippedRows = new AtomicInteger(0);

    public static class Summary {
        public final int skus;
        public final int rows;
        public final int skipped;
        public final ConcurrentHashMap<String, Double> totals;

        public Summary(int skus, int rows, int skipped, ConcurrentHashMap<String, Double> totals) {
            this.skus = skus;
            this.rows = rows;
            this.skipped = skipped;
            this.totals = totals;
        }
    }

    static void accumulate(Map<String, String> row) {
        String sku = row.get("sku");
        try {
            double value = Integer.parseInt(row.get("quantity")) * Double.parseDouble(row.get("unit_price").replace("$", ""));
            totals.merge(sku, value, Double::sum);
            rowCount.incrementAndGet();
        } catch (NumberFormatException e) {
            skippedRows.incrementAndGet();
        }
    }

    static void worker(List<Map<String, String>> rows) {
        for (Map<String, String> row : rows) {
            accumulate(row);
        }
    }

    public static List<Map<String, String>> load(String path) throws IOException {
        List<Map<String, String>> out = new ArrayList<>();
        try (Reader reader = Files.newBufferedReader(Path.of(path));
             CSVParser csvParser = new CSVParser(reader, CSVFormat.DEFAULT.withFirstRecordAsHeader())) {
            for (CSVRecord csvRecord : csvParser) {
                Map<String, String> row = new HashMap<>();
                for (String header : csvParser.getHeaderNames()) {
                    row.put(header, csvRecord.get(header));
                }
                out.add(row);
            }
        }
        return out;
    }

    public static Summary summarize(String path) throws Exception {
        totals.clear();
        rowCount.set(0);
        skippedRows.set(0);
        List<Map<String, String>> rows = load(path);

        Set<String> skus = new HashSet<>();
        for (Map<String, String> row : rows) {
            skus.add(row.get("sku"));
        }

        if (WORKERS_ENABLED) {
            ForkJoinPool pool = new ForkJoinPool(NUM_WORKERS);
            List<Callable<Void>> tasks = new ArrayList<>();
            int chunk = Math.max(1, rows.size() / NUM_WORKERS);
            for (int i = 0; i < rows.size(); i += chunk) {
                List<Map<String, String>> slice = rows.subList(i, Math.min(i + chunk, rows.size()));
                tasks.add(() -> {
                    worker(slice);
                    return null;
                });
            }
            pool.invokeAll(tasks);
            pool.shutdown();
        } else {
            worker(rows);
        }

        return new Summary(skus.size(), rowCount.get(), skippedRows.get(), totals);
    }

    public static void main(String[] args) throws Exception {
        String path = args.length > 0 ? args[0] : Path.of("data", "feed.csv").toString();
        Summary result = summarize(path);
        System.out.printf("imported %d rows covering %d SKUs, skipped %d rows%n", result.rows, result.skus, result.skipped);
        List<String> keys = new ArrayList<>(result.totals.keySet());
        Collections.sort(keys);
        for (String sku : keys) {
            System.out.printf("  %s: %.2f%n", sku, result.totals.get(sku));
        }
    }
}
